import React, { useEffect, useState } from 'react';
import { FileListItemType } from '../../FileMultiUploader.types';
import { formatFileSize } from '../../utils/utils';
import { IconButtons } from '../IconButtons/IconButtons';
import { DefaultFileImage } from '../default-file-image';
import { DefaultImage } from '../default-image';
import { ErrorImage } from '../error-image';
import {
  FileListContentContainer,
  FileListDescriptionContainer,
  FileListItemContainer,
  FileListItemImage,
  FileListItemImageContainer,
  FileLoaderText,
  FileTextContainer,
  FileTitle,
  ProgressBarContainer,
  StyledImg,
} from './FileListItem.styles';

const ImagesTypes = {
  error: ErrorImage,
  image: DefaultImage,
  file: DefaultFileImage,
};

/* eslint-disable max-params */
const getFileLoaderText = (
  status: string,
  size: string,
  feedbackMessage: string,
  errors?: string[],
  progress?: number
): string => {
  switch (status) {
    case 'feedback':
      return feedbackMessage;
    case 'error':
      return errors?.join(', ') || '';
    case 'uploading':
      return `${progress}%`;
    case 'uploaded':
      return size;
    /* istanbul ignore next */
    default:
      return '';
  }
};
/* eslint-enable max-params */

const statusToShowProgressBar = ['uploading', 'feedback'];
const shouldNotShowImageStatus = ['uploading', 'error'];

export const FileListItem = ({
  file,
  feedbackMessage = 'Done!',
  feedbackTimeout = 3000,
  imageFit,
  hasPreviewButton,
  hasProgress,
  setLoadingStatus,
  setProgress: setFileProgress,
  size,
  setErrors,
  onClean,
  onUpload,
  uploadFile,
  onProgress,
  onPreview,
}: FileListItemType): React.ReactElement => {
  const [progress, setProgress] = useState(file.progress);

  const isImage = file?.type.startsWith('image/');
  const type = isImage ? 'image' : 'file';
  const imageType = file.loadingStatus === 'error' ? 'error' : type;
  const ImageComponent = ImagesTypes[imageType];
  const shouldShowProgressBar = statusToShowProgressBar.includes(file.loadingStatus);

  const fileLoaderText = getFileLoaderText(
    file.loadingStatus,
    formatFileSize(file?.size),
    feedbackMessage,
    file?.errors,
    progress
  );

  const hasFileUrl = file.url !== undefined && file.url !== '';
  const shouldShowImage =
    isImage && !shouldNotShowImageStatus.includes(file.loadingStatus) && hasFileUrl;

  const handleOnPreview = (event: React.MouseEvent) => {
    event.stopPropagation();
    onPreview?.(file);
  };

  const handleOnClean = (event: React.MouseEvent) => {
    event.stopPropagation();
    onClean?.(file);
  };

  /* eslint-disable react-hooks/exhaustive-deps */
  useEffect(() => {
    async function upload() {
      let url = '';
      if (uploadFile) {
        try {
          url = await uploadFile(file.fileContent, setProgress);
          setFileProgress(file.id, progress);
        } catch (error) {
          setLoadingStatus(file.id, 'error');
          setErrors(file.id, [(error as any).message || 'Error on upload file service.']);
          return;
        }
      } else if (onProgress) {
        onProgress(setProgress);
        setFileProgress(file.id, progress);
        url = URL.createObjectURL(file.fileContent);
      } else {
        url = URL.createObjectURL(file.fileContent);
      }
      onUpload(file, url);
    }

    upload();
  }, []);

  useEffect(() => {
    if (file?.errors && file?.errors?.length > 0) {
      setLoadingStatus(file.id, 'error');
    }
    if (file.loadingStatus === 'uploaded' || file.loadingStatus === 'error') {
      return;
    }
    if (hasProgress) {
      if (progress === 100) {
        setLoadingStatus(file.id, 'feedback');
        setTimeout(() => {
          setLoadingStatus(file.id, 'uploaded');
        }, feedbackTimeout);
      }
    }
  }, [file.errors, uploadFile, onProgress, progress, file.loadingStatus]);
  /* eslint-enable react-hooks/exhaustive-deps */

  return (
    <FileListItemContainer size={size}>
      <FileListContentContainer size={size}>
        <FileListDescriptionContainer size={size}>
          <FileListItemImageContainer size={size}>
            <FileListItemImage>
              {shouldShowImage ? (
                <StyledImg src={file?.url} alt={file.name} style={{ objectFit: imageFit }} />
              ) : (
                <ImageComponent />
              )}
            </FileListItemImage>
          </FileListItemImageContainer>
          <FileTextContainer size={size}>
            <FileTitle>{file?.name}</FileTitle>
            <FileLoaderText error={file.loadingStatus === 'error'}>{fileLoaderText}</FileLoaderText>
          </FileTextContainer>
        </FileListDescriptionContainer>
        {!shouldShowProgressBar && (
          <IconButtons
            shouldShowPreviewButton={hasPreviewButton && file.loadingStatus === 'uploaded'}
            handleOnPreview={handleOnPreview}
            handleOnClean={handleOnClean}
          />
        )}
      </FileListContentContainer>
      {shouldShowProgressBar && (
        <ProgressBarContainer type={file.loadingStatus}>
          <progress max="100" value={`${progress}`} />
        </ProgressBarContainer>
      )}
    </FileListItemContainer>
  );
};
